CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, name TEXT NOT NULL, owner_id TEXT NOT NULL, revision BIGINT NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS boards (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), name TEXT NOT NULL, revision BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS design_versions (id TEXT PRIMARY KEY, board_id TEXT NOT NULL REFERENCES boards(id), sequence INTEGER NOT NULL, status TEXT NOT NULL, preview JSONB NOT NULL, revision BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS annotations (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), board_id TEXT NOT NULL REFERENCES boards(id), version_id TEXT NOT NULL REFERENCES design_versions(id), node_key TEXT NOT NULL, state TEXT NOT NULL, body TEXT NOT NULL, revision BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS project_members (project_id TEXT NOT NULL REFERENCES projects(id), actor_id TEXT NOT NULL, email TEXT NOT NULL, role TEXT NOT NULL, revision BIGINT NOT NULL, PRIMARY KEY (project_id, actor_id), UNIQUE (project_id, email));
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, actor_id TEXT NOT NULL, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, occurred_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, event_id TEXT NOT NULL, recipient_id TEXT NOT NULL, attempt INTEGER NOT NULL, lease_owner TEXT NOT NULL, lease_expires_at TIMESTAMPTZ, sent_at TIMESTAMPTZ, UNIQUE (event_id, recipient_id));
